<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import {
  GetEnrichAliasList,
  GetEnrichConsistency,
  GetEnrichReviewList,
  GetEnrichStateList,
  GetEnrichTagList,
  GetEnrichWorkerConfig,
  PostEnrichAliasAdd,
  PostEnrichAliasDelete,
  PostEnrichBackfill,
  PostEnrichGoldenSet,
  PostEnrichRequeue,
  PostEnrichReviewSet,
  PostEnrichTagApprove,
  PostEnrichTagDeprecate,
  PostEnrichTagMerge,
  PostEnrichTagReactivate,
} from "@/apis/problem-enrichment";
import type {
  EnrichConsistencyReport,
  EnrichReviewItem,
  EnrichStateItem,
  EnrichStateStatus,
  EnrichTag,
  EnrichWorkerConfig,
  TagAlias,
} from "@/types/problem-enrichment";
import { TagStatus } from "@/types/problem-enrichment";
import { handleGotoProblem } from "@/util/router";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

// ───────────────────────── 通用 ─────────────────────────

const activeTab = ref("state");
const pageSize = isMobile.value ? 20 : 50;

const stateStatusOptions = [
  { label: "未处理", value: 0 },
  { label: "排队", value: 1 },
  { label: "处理中", value: 2 },
  { label: "成功", value: 3 },
  { label: "失败", value: 4 },
];

const stateStatusText: Record<number, string> = {
  0: "未处理",
  1: "排队",
  2: "处理中",
  3: "成功",
  4: "失败",
};

const stateStatusTheme: Record<number, string> = {
  0: "default",
  1: "warning",
  2: "primary",
  3: "success",
  4: "danger",
};

const tagStatusText: Record<number, string> = {
  0: "候选",
  1: "正式",
  2: "已合并",
  3: "已归档",
};

const tagStatusTheme: Record<number, string> = {
  0: "warning",
  1: "success",
  2: "default",
  3: "danger",
};

const taskTypeText: Record<string, string> = {
  summary: "摘要",
  tags: "标签",
  difficulty: "难度",
  quality: "质量",
  suggestion: "建议",
};

const visibilityText: Record<string, string> = {
  public: "公开",
  internal: "内部",
  sensitive: "敏感",
};

const reviewStatusText: Record<string, string> = {
  "": "—",
  pending: "待审核",
  approved: "已通过",
  rejected: "已驳回",
};

// ───────────────────────── Tab1：状态监控 ─────────────────────────

const workerConfig = ref<EnrichWorkerConfig | null>(null);
const stateList = ref<EnrichStateItem[]>([]);
const stateTotal = ref(0);
const statePage = ref(1);
const stateFilter = ref<number[]>([]);
const stateLoading = ref(false);
const backfilling = ref(false);

const statePagination = computed(() => ({
  current: statePage.value,
  pageSize,
  total: stateTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

const stateColumns = [
  { colKey: "problem_id", title: "题目", minWidth: 160 },
  { colKey: "status", title: "状态", width: 90 },
  { colKey: "stage", title: "阶段", width: 110 },
  { colKey: "attempt", title: "尝试", width: 70 },
  { colKey: "message", title: "信息", minWidth: 180, ellipsis: true },
  { colKey: "modify_time", title: "更新时间", width: 170 },
  { colKey: "operation", title: "操作", width: 80, fixed: "right" as const },
];

const tagColumns = [
  { colKey: "name", title: "标签", minWidth: 160 },
  { colKey: "status", title: "状态", width: 150 },
  { colKey: "usage_count", title: "命中题数", width: 100 },
  { colKey: "operation", title: "操作", width: 280, fixed: "right" as const },
];

const consistencyColumns = [
  { colKey: "problem_id", title: "题目", width: 120 },
  { colKey: "golden", title: "黄金集档位", width: 130 },
  { colKey: "latest_ai", title: "最新 AI 档位", width: 140 },
  { colKey: "within_one", title: "是否 ±1 档内", width: 140 },
];

const configRows = computed(() => {
  const c = workerConfig.value;
  if (!c) {
    return [];
  }
  // worker 常驻 judge 进程：web 不持有运行参数，只展示归属与排查入口
  if (c.Tier === "judge") {
    return [
      { label: "运行位置", value: "judge 评测进程（常驻）" },
      { label: "配置位置", value: "judge 配置 ai.problem-enrichment" },
      { label: "实时进度", value: "见下方状态列表与调用账本" },
    ];
  }
  return [
    { label: "总开关", value: c.Enabled ? "启用" : "关闭" },
    { label: "干跑模式", value: c.DryRun ? "干跑（不调 LLM）" : "真实调用" },
    { label: "模型", value: c.Model || "（未配置）" },
    { label: "轮询间隔", value: `${Math.round((c.Interval ?? 0) / 1e9)} 秒` },
    { label: "每轮题数", value: String(c.BatchSize ?? 0) },
    { label: "最大尝试", value: String(c.MaxAttempt ?? 0) },
    { label: "卡死回收", value: `${Math.round((c.StaleTimeout ?? 0) / 60e9)} 分钟` },
    { label: "每日 token 上限", value: (c.DailyTokenLimit ?? 0) > 0 ? String(c.DailyTokenLimit) : "不限" },
    { label: "每日题数上限", value: (c.DailyProblemLimit ?? 0) > 0 ? String(c.DailyProblemLimit) : "不限" },
    { label: "候选自动晋升阈值", value: `${c.CandidatePromoteUsage ?? 0} 题` },
  ];
});

const fetchWorkerConfig = async () => {
  try {
    const res = await GetEnrichWorkerConfig();
    if (res.code === 0) {
      workerConfig.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  }
};

const fetchStateList = async () => {
  stateLoading.value = true;
  try {
    const res = await GetEnrichStateList(
      stateFilter.value.length > 0 ? (stateFilter.value as EnrichStateStatus[]) : null,
      statePage.value,
      pageSize
    );
    if (res.code === 0) {
      stateList.value = res.data.list;
      stateTotal.value = res.data.total;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    stateLoading.value = false;
  }
};

const onStatePageChange = (info: { current: number }) => {
  statePage.value = info.current;
  fetchStateList();
};

const onStateFilterChange = () => {
  statePage.value = 1;
  fetchStateList();
};

const handleRequeue = async (row: EnrichStateItem) => {
  try {
    const res = await PostEnrichRequeue(row.problem_id);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已重新入队");
      fetchStateList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

const handleBackfill = async () => {
  backfilling.value = true;
  try {
    const res = await PostEnrichBackfill();
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, `补插完成，新增 ${res.data.inserted} 行`);
      fetchStateList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    backfilling.value = false;
  }
};

// ───────────────────────── Tab2：词表治理 ─────────────────────────

const tagList = ref<EnrichTag[]>([]);
const tagTotal = ref(0);
const tagPage = ref(1);
const tagFilter = ref<number[]>([0, 1, 3]);
const tagLoading = ref(false);
const tagMap = ref<Map<number, EnrichTag>>(new Map());

// 合并对话框
const mergeDialogVisible = ref(false);
const mergeSource = ref<EnrichTag | null>(null);
const mergeTargetId = ref<number | undefined>(undefined);
const mergeSubmitting = ref(false);

// 别名对话框
const aliasDialogVisible = ref(false);
const aliasTag = ref<EnrichTag | null>(null);
const aliasList = ref<TagAlias[]>([]);
const aliasLoading = ref(false);
const aliasInput = ref("");
const aliasSubmitting = ref(false);

const tagPagination = computed(() => ({
  current: tagPage.value,
  pageSize,
  total: tagTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

// 合并目标候选：正式词，排除自身与已合并词
const mergeTargetOptions = computed(() =>
  tagList.value
    .filter((t) => t.status === TagStatus.Active && t.id !== mergeSource.value?.id)
    .map((t) => ({ label: t.name, value: t.id }))
);

const fetchTagList = async () => {
  tagLoading.value = true;
  try {
    const res = await GetEnrichTagList(tagFilter.value.length > 0 ? tagFilter.value : null, tagPage.value, pageSize);
    if (res.code === 0) {
      tagList.value = res.data.list;
      tagTotal.value = res.data.total;
      const m = new Map<number, EnrichTag>();
      res.data.list.forEach((t) => m.set(t.id, t));
      tagMap.value = m;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    tagLoading.value = false;
  }
};

const onTagPageChange = (info: { current: number }) => {
  tagPage.value = info.current;
  fetchTagList();
};

const onTagFilterChange = () => {
  tagPage.value = 1;
  fetchTagList();
};

const handleApproveTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagApprove(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已批准为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleDeprecateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagDeprecate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已归档");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleReactivateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagReactivate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已恢复为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const openMergeDialog = (tag: EnrichTag) => {
  mergeSource.value = tag;
  mergeTargetId.value = undefined;
  mergeDialogVisible.value = true;
};

const handleMergeSubmit = async () => {
  if (!mergeSource.value || !mergeTargetId.value) {
    return;
  }
  mergeSubmitting.value = true;
  try {
    const res = await PostEnrichTagMerge(mergeSource.value.id, mergeTargetId.value);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "合并完成，历史关联已保留");
      mergeDialogVisible.value = false;
      fetchTagList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    mergeSubmitting.value = false;
  }
};

const mergedTargetName = (row: EnrichTag) => {
  if (row.merged_to_id == null) {
    return "";
  }
  return tagMap.value.get(row.merged_to_id)?.name ?? `#${row.merged_to_id}`;
};

const openAliasDialog = async (tag: EnrichTag) => {
  aliasTag.value = tag;
  aliasInput.value = "";
  aliasDialogVisible.value = true;
  aliasLoading.value = true;
  try {
    const res = await GetEnrichAliasList(tag.id);
    if (res.code === 0) {
      aliasList.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasLoading.value = false;
  }
};

const handleAliasAdd = async () => {
  if (!aliasTag.value || !aliasInput.value.trim()) {
    return;
  }
  aliasSubmitting.value = true;
  try {
    const res = await PostEnrichAliasAdd(aliasTag.value.id, aliasInput.value.trim());
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "别名已登记");
      aliasInput.value = "";
      const refresh = await GetEnrichAliasList(aliasTag.value.id);
      if (refresh.code === 0) {
        aliasList.value = refresh.data;
      }
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasSubmitting.value = false;
  }
};

const handleAliasDelete = async (id: number) => {
  const res = await PostEnrichAliasDelete(id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "别名已删除");
    if (aliasTag.value) {
      const refresh = await GetEnrichAliasList(aliasTag.value.id);
      if (refresh.code === 0) {
        aliasList.value = refresh.data;
      }
    }
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// ───────────────────────── Tab3：标注审核（Prodigy 键盘流） ─────────────────────────

const reviewList = ref<EnrichReviewItem[]>([]);
const reviewTotal = ref(0);
const reviewPage = ref(1);
const reviewLoading = ref(false);
const reviewCursor = ref(0); // 当前选中行（页内下标）
const reviewSubmitting = ref(false);
const rawDialogVisible = ref(false);
const rawDialogContent = ref<EnrichReviewItem | null>(null);

const currentReview = computed(() => reviewList.value[reviewCursor.value] ?? null);

const fetchReviewList = async () => {
  reviewLoading.value = true;
  try {
    const res = await GetEnrichReviewList(reviewPage.value, pageSize);
    if (res.code === 0) {
      reviewList.value = res.data.list;
      reviewTotal.value = res.data.total;
      reviewCursor.value = 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewLoading.value = false;
  }
};

const onReviewPageChange = async (info: { current: number }) => {
  reviewPage.value = info.current;
  await fetchReviewList();
};

const prettyJSON = (obj: unknown): string => {
  try {
    return JSON.stringify(obj, null, 2);
  } catch {
    return String(obj);
  }
};

const reviewDecision = async (status: "approved" | "rejected") => {
  const item = currentReview.value;
  if (!item || reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichReviewSet(item.id, status);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, status === "approved" ? "已通过" : "已驳回");
      reviewList.value.splice(reviewCursor.value, 1);
      reviewTotal.value -= 1;
      if (reviewCursor.value >= reviewList.value.length && reviewCursor.value > 0) {
        reviewCursor.value -= 1;
      }
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const toggleGolden = async () => {
  const item = currentReview.value;
  if (!item || reviewSubmitting.value) {
    return;
  }
  reviewSubmitting.value = true;
  try {
    const res = await PostEnrichGoldenSet(item.id, !item.golden);
    if (res.code === 0) {
      item.golden = !item.golden;
      ShowTextTipsInfo(globalProperties, item.golden ? "已冻结为黄金集基准" : "已解除黄金集");
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    reviewSubmitting.value = false;
  }
};

const openRawDialog = (item: EnrichReviewItem) => {
  rawDialogContent.value = item;
  rawDialogVisible.value = true;
};

// 键盘流：a 通过 / x 驳回 / g 黄金集 / ↑↓ 切换（仅审核 tab 且无弹窗、焦点不在输入框时）
const onReviewKeydown = (e: KeyboardEvent) => {
  if (activeTab.value !== "review" || rawDialogVisible.value || mergeDialogVisible.value || aliasDialogVisible.value) {
    return;
  }
  const target = e.target as HTMLElement | null;
  if (target && ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)) {
    return;
  }
  if (e.key === "a" || e.key === "A") {
    e.preventDefault();
    reviewDecision("approved");
  } else if (e.key === "x" || e.key === "X") {
    e.preventDefault();
    reviewDecision("rejected");
  } else if (e.key === "g" || e.key === "G") {
    e.preventDefault();
    toggleGolden();
  } else if (e.key === "ArrowDown") {
    e.preventDefault();
    if (reviewCursor.value < reviewList.value.length - 1) {
      reviewCursor.value += 1;
    }
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    if (reviewCursor.value > 0) {
      reviewCursor.value -= 1;
    }
  }
};

// ───────────────────────── Tab4：黄金集一致率 ─────────────────────────

const consistencyReport = ref<EnrichConsistencyReport | null>(null);
const consistencyLoading = ref(false);

const fetchConsistency = async () => {
  consistencyLoading.value = true;
  try {
    const res = await GetEnrichConsistency();
    if (res.code === 0) {
      consistencyReport.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    consistencyLoading.value = false;
  }
};

const gradeName = (grade: number): string => {
  return ["", "入门", "普及", "提高", "省选", "NOI"][grade] ?? "—";
};

// tab 切换时懒加载
const onTabChange = (name: string) => {
  activeTab.value = name;
  if (name === "state" && stateList.value.length === 0) {
    fetchWorkerConfig();
    fetchStateList();
  } else if (name === "tag" && tagList.value.length === 0) {
    fetchTagList();
  } else if (name === "review") {
    fetchReviewList();
  } else if (name === "golden") {
    fetchConsistency();
  }
};

const gotoProblem = (problemKey: string) => {
  if (problemKey) {
    handleGotoProblem(problemKey);
  }
};

onMounted(() => {
  fetchWorkerConfig();
  fetchStateList();
  window.addEventListener("keydown", onReviewKeydown);
});

onBeforeUnmount(() => {
  window.removeEventListener("keydown", onReviewKeydown);
});
</script>

<template>
  <div class="enrich-admin">
    <t-card class="enrich-header-card">
      <div class="enrich-header">
        <h2>题目智能富化后台</h2>
        <t-tag
          v-if="workerConfig"
          :theme="workerConfig.Tier === 'judge' ? 'primary' : workerConfig.Enabled ? 'success' : 'default'"
          variant="light"
        >
          {{
            workerConfig.Tier === "judge"
              ? "judge 进程运行"
              : workerConfig.Enabled
                ? workerConfig.DryRun
                  ? "干跑中"
                  : "运行中"
                : "已停用"
          }}
        </t-tag>
      </div>
      <p class="enrich-subtitle">
        摘要 / 标签 / 难度 / 质量由 AI 后处理流水线产出。质量分与改进建议仅内部可见；候选标签需经生命周期治理后进入正式词表。
      </p>
    </t-card>

    <t-card class="enrich-body-card">
      <t-tabs v-model="activeTab" @change="onTabChange">
        <!-- ───────── 状态监控 ───────── -->
        <t-tab-panel value="state" label="状态监控">
          <t-row :gutter="12">
            <t-col :xs="12" :sm="12" :md="6">
              <t-descriptions
                :column="isMobile ? 1 : 2"
                bordered
                :data="configRows"
                class="enrich-config"
              />
            </t-col>
          </t-row>

          <div class="enrich-toolbar">
            <t-select
              v-model="stateFilter"
              :options="stateStatusOptions"
              multiple
              clearable
              placeholder="按状态筛选"
              :min-collapsed-num="1"
              style="min-width: 240px"
              @change="onStateFilterChange"
            />
            <t-button theme="primary" variant="outline" :loading="backfilling" @click="handleBackfill">
              补插存量题目
            </t-button>
            <t-button variant="outline" @click="fetchStateList">刷新</t-button>
          </div>

          <div class="enrich-table-wrap">
            <t-table
              :data="stateList"
              :columns="stateColumns"
              :loading="stateLoading"
              row-key="problem_id"
              table-layout="auto"
              :pagination="statePagination"
              @page-change="onStatePageChange"
            >
              <template #problem_id="{ row }">
                <t-button variant="text" @click="gotoProblem(row.problem_key)">
                  {{ row.problem_key || row.problem_id }}
                </t-button>
                <div class="enrich-problem-title">{{ row.problem_title }}</div>
              </template>
              <template #status="{ row }">
                <t-tag :theme="stateStatusTheme[row.status]" variant="light">
                  {{ stateStatusText[row.status] }}
                </t-tag>
              </template>
              <template #stage="{ row }">{{ row.stage || "—" }}</template>
              <template #attempt="{ row }">{{ row.attempt }}</template>
              <template #message="{ row }">
                <span :title="row.message || ''" class="enrich-ellipsis">{{ row.message || "—" }}</span>
              </template>
              <template #modify_time="{ row }">{{ new Date(row.modify_time).toLocaleString() }}</template>
              <template #operation="{ row }">
                <t-button size="small" variant="text" theme="primary" @click="handleRequeue(row)">重跑</t-button>
              </template>
            </t-table>
          </div>
        </t-tab-panel>

        <!-- ───────── 词表治理 ───────── -->
        <t-tab-panel value="tag" label="词表治理">
          <div class="enrich-toolbar">
            <t-select
              v-model="tagFilter"
              :options="[
                { label: '候选', value: 0 },
                { label: '正式', value: 1 },
                { label: '已合并', value: 2 },
                { label: '已归档', value: 3 },
              ]"
              multiple
              clearable
              placeholder="按状态筛选"
              style="min-width: 240px"
              @change="onTagFilterChange"
            />
            <t-button variant="outline" @click="fetchTagList">刷新</t-button>
          </div>

          <div class="enrich-table-wrap">
            <t-table
              :data="tagList"
              :columns="tagColumns"
              :loading="tagLoading"
              row-key="id"
              table-layout="auto"
              :pagination="tagPagination"
              @page-change="onTagPageChange"
            >
              <template #name="{ row }">
                <span>{{ row.name }}</span>
                <t-tag v-if="row.source === 'ai'" size="small" theme="primary" variant="outline" class="enrich-ai-tag">
                  AI
                </t-tag>
              </template>
              <template #status="{ row }">
                <t-tag :theme="tagStatusTheme[row.status]" variant="light">{{ tagStatusText[row.status] }}</t-tag>
                <span v-if="row.status === 2 && row.merged_to_id" class="enrich-merge-target">
                  → {{ mergedTargetName(row) }}
                </span>
              </template>
              <template #usage_count="{ row }">{{ row.usage_count }}</template>
              <template #operation="{ row }">
                <t-space size="small">
                  <t-button
                    v-if="row.status === 0"
                    size="small"
                    variant="text"
                    theme="success"
                    @click="handleApproveTag(row)"
                  >
                    批准
                  </t-button>
                  <t-button
                    v-if="row.status !== 2"
                    size="small"
                    variant="text"
                    theme="primary"
                    @click="openMergeDialog(row)"
                  >
                    合并
                  </t-button>
                  <t-button
                    v-if="row.status === 3"
                    size="small"
                    variant="text"
                    theme="success"
                    @click="handleReactivateTag(row)"
                  >
                    恢复
                  </t-button>
                  <t-button
                    v-if="row.status !== 2 && row.status !== 3"
                    size="small"
                    variant="text"
                    theme="danger"
                    @click="handleDeprecateTag(row)"
                  >
                    归档
                  </t-button>
                  <t-button size="small" variant="text" @click="openAliasDialog(row)">别名</t-button>
                </t-space>
              </template>
            </t-table>
          </div>
        </t-tab-panel>

        <!-- ───────── 标注审核 ───────── -->
        <t-tab-panel value="review" label="标注审核">
          <div class="enrich-toolbar">
            <t-alert theme="info" :message="`键盘流：A 通过 · X 驳回 · G 冻结/解冻黄金集 · ↑↓ 切换（共 ${reviewTotal} 条待审）`" />
            <t-button variant="outline" :loading="reviewLoading" @click="fetchReviewList">刷新</t-button>
          </div>

          <div v-if="reviewList.length === 0 && !reviewLoading" class="enrich-empty">暂无待审核标注</div>

          <div
            v-for="(item, index) in reviewList"
            :key="item.id"
            class="review-card"
            :class="{ 'review-card-active': index === reviewCursor }"
            @click="reviewCursor = index"
          >
            <div class="review-card-head">
              <t-space size="small">
                <t-tag theme="primary" variant="light">{{ taskTypeText[item.task_type] || item.task_type }}</t-tag>
                <t-tag variant="outline">{{ visibilityText[item.visibility] || item.visibility }}</t-tag>
                <t-tag v-if="item.golden" theme="warning" variant="dark">黄金集</t-tag>
                <span class="review-title">{{ item.problem_title || `题目 #${item.problem_id}` }}</span>
              </t-space>
              <t-space size="small">
                <span class="review-meta">置信度 {{ (item.confidence * 100).toFixed(0) }}%</span>
                <span class="review-meta">{{ item.model }}</span>
                <t-button size="small" variant="text" @click.stop="openRawDialog(item)">原始响应</t-button>
              </t-space>
            </div>
            <pre class="review-payload">{{ prettyJSON(item.payload) }}</pre>
            <div class="review-card-foot">
              <t-space size="small">
                <t-button
                  size="small"
                  theme="success"
                  :loading="reviewSubmitting && index === reviewCursor"
                  @click.stop="reviewCursor = index; reviewDecision('approved')"
                >
                  通过 (A)
                </t-button>
                <t-button
                  size="small"
                  theme="danger"
                  variant="outline"
                  @click.stop="reviewCursor = index; reviewDecision('rejected')"
                >
                  驳回 (X)
                </t-button>
                <t-button size="small" variant="outline" @click.stop="reviewCursor = index; toggleGolden()">
                  {{ item.golden ? "解除黄金集 (G)" : "冻结黄金集 (G)" }}
                </t-button>
                <span class="review-meta">{{ reviewStatusText[item.review_status] }}</span>
              </t-space>
            </div>
          </div>

          <div v-if="reviewTotal > pageSize" class="enrich-pagination">
            <t-pagination
              :current="reviewPage"
              :pageSize="pageSize"
              :total="reviewTotal"
              @change="onReviewPageChange"
            />
          </div>
        </t-tab-panel>

        <!-- ───────── 黄金集一致率 ───────── -->
        <t-tab-panel value="golden" label="黄金集与一致率">
          <t-button variant="outline" :loading="consistencyLoading" @click="fetchConsistency">重新计算</t-button>

          <div v-if="consistencyReport" class="consistency-body">
            <t-alert
              v-if="consistencyReport.golden_total === 0"
              theme="warning"
              message="还没有冻结任何黄金集基准。请在「标注审核」中把人工确认过的难度标注冻结为黄金集（建议 50~100 题）。"
              class="consistency-alert"
            />
            <t-row :gutter="12" class="consistency-cards">
              <t-col :xs="12" :sm="6" :md="3">
                <t-card class="metric-card">
                  <div class="metric-value">{{ consistencyReport.golden_total }}</div>
                  <div class="metric-label">黄金集题数</div>
                </t-card>
              </t-col>
              <t-col :xs="12" :sm="6" :md="3">
                <t-card class="metric-card">
                  <div class="metric-value">{{ consistencyReport.comparable }}</div>
                  <div class="metric-label">可对比</div>
                </t-card>
              </t-col>
              <t-col :xs="12" :sm="6" :md="3">
                <t-card class="metric-card">
                  <div class="metric-value">{{ consistencyReport.missing }}</div>
                  <div class="metric-label">AI 缺失</div>
                </t-card>
              </t-col>
              <t-col :xs="12" :sm="6" :md="3">
                <t-card class="metric-card" :class="{ 'metric-pass': consistencyReport.passed }">
                  <div class="metric-value">{{ (consistencyReport.within_one_rate * 100).toFixed(0) }}%</div>
                  <div class="metric-label">
                    ±1 档一致率（门槛 {{ (consistencyReport.threshold * 100).toFixed(0) }}%）
                  </div>
                </t-card>
              </t-col>
            </t-row>

            <t-tag :theme="consistencyReport.passed ? 'success' : 'warning'" variant="light" class="consistency-verdict">
              {{ consistencyReport.passed ? "达到自动生效门槛" : "未达门槛，难度标注仅提示不自动生效" }}
            </t-tag>

            <div v-if="consistencyReport.details.length > 0" class="enrich-table-wrap">
              <t-table
                :data="consistencyReport.details"
                :columns="consistencyColumns"
                row-key="problem_id"
                table-layout="auto"
                :max-height="isMobile ? 360 : 520"
              >
                <template #problem_id="{ row }">
                  <span>#{{ row.problem_id }}</span>
                </template>
                <template #golden="{ row }">{{ gradeName(row.golden) }}</template>
                <template #latest_ai="{ row }">{{ row.latest_ai < 0 ? "缺失" : gradeName(row.latest_ai) }}</template>
                <template #within_one="{ row }">
                  <t-tag :theme="row.within_one ? 'success' : 'danger'" variant="light">
                    {{ row.within_one ? "±1 档内" : "偏差>1" }}
                  </t-tag>
                </template>
              </t-table>
            </div>
          </div>
        </t-tab-panel>
      </t-tabs>
    </t-card>

    <!-- 合并对话框 -->
    <t-dialog
      v-model:visible="mergeDialogVisible"
      header="合并标签"
      :confirm-on-enter="false"
      :confirm-loading="mergeSubmitting"
      @confirm="handleMergeSubmit"
    >
      <p v-if="mergeSource">
        将标签「<b>{{ mergeSource.name }}</b>」的全部题目关联与别名并入目标标签；
        源标签置为「已合并」并保留指向，历史关联不丢失。
      </p>
      <t-select
        v-model="mergeTargetId"
        :options="mergeTargetOptions"
        filterable
        placeholder="选择合并目标（正式标签）"
      />
    </t-dialog>

    <!-- 别名对话框 -->
    <t-dialog v-model:visible="aliasDialogVisible" header="标签别名管理" :footer="false" width="560px">
      <p v-if="aliasTag">标签「<b>{{ aliasTag.name }}</b>」的归一别名（AI/人工输出这些词时直接映射到该标签）：</p>
      <t-loading :loading="aliasLoading">
        <div v-if="aliasList.length === 0" class="enrich-empty">暂无别名</div>
        <div v-for="a in aliasList" :key="a.id" class="alias-row">
          <span>{{ a.alias }}</span>
          <t-button size="small" variant="text" theme="danger" @click="handleAliasDelete(a.id)">删除</t-button>
        </div>
      </t-loading>
      <t-input
        v-model="aliasInput"
        placeholder="新增别名（自动做全半角/大小写归一）"
        class="alias-input"
        @enter="handleAliasAdd"
      />
      <t-button theme="primary" :loading="aliasSubmitting" style="margin-top: 8px" @click="handleAliasAdd">
        添加别名
      </t-button>
    </t-dialog>

    <!-- 原始响应对话框（审核：看 raw response） -->
    <t-dialog
      v-model:visible="rawDialogVisible"
      header="模型原始响应"
      :footer="false"
      width="720px"
      :destroy-on-close="true"
    >
      <template v-if="rawDialogContent">
        <t-descriptions
          :column="1"
          bordered
          :data="[
            { label: '题目', value: rawDialogContent.problem_title || `#${rawDialogContent.problem_id}` },
            { label: '模型', value: rawDialogContent.model },
            { label: 'Prompt 版本', value: rawDialogContent.prompt_ver || '—' },
            { label: 'Schema 版本', value: rawDialogContent.schema_ver || '—' },
          ]"
        />
        <h4>结构化 payload</h4>
        <pre class="review-payload">{{ prettyJSON(rawDialogContent.payload) }}</pre>
        <h4>raw_response</h4>
        <pre class="review-raw">{{ rawDialogContent.raw_response || "（未留存）" }}</pre>
      </template>
    </t-dialog>
  </div>
</template>

