// 题目 AI 后处理（富化）后台的类型定义。
// 字段与后端 foundation-model / foundation-service 的 JSON tag 一一对应。

// 富化状态机 status（problem_enrich_state）
export enum EnrichStateStatus {
  Init = 0, // 未处理
  Queued = 1, // 排队
  Running = 2, // 处理中
  Success = 3, // 成功
  Failed = 4, // 失败（重试超上限终态）
}

export interface ProblemEnrichState {
  problem_id: number;
  status: EnrichStateStatus;
  stage?: string;
  fingerprint: string;
  attempt: number;
  message?: string;
  worker?: string;
  insert_time: string;
  modify_time: string;
}

// 后台状态列表行：状态 + 题目定位
export interface EnrichStateItem extends ProblemEnrichState {
  problem_key: string;
  problem_title: string;
}

// 标签生命周期 status（tag）
export enum TagStatus {
  Candidate = 0, // 候选
  Active = 1, // 正式
  Merged = 2, // 已合并
  Deprecated = 3, // 已归档
}

export interface EnrichTag {
  id: number;
  name: string;
  status: TagStatus;
  merged_to_id?: number;
  source: string; // human / ai
  usage_count: number;
}

export interface TagAlias {
  id: number;
  alias: string;
  tag_id: number;
  inserter: number;
  insert_time: string;
}

// 标注审核状态
export type ReviewStatus = "" | "pending" | "approved" | "rejected";

// 各 task_type 的 payload（与后端 jsonb 结构一致）
export interface EnrichSummaryPayload {
  oneliner: string;
  io_points: string;
  scale: string;
}

export interface EnrichDifficultyPayload {
  overall: number;
  thinking: number;
  algorithm: number;
  implementation: number;
  pitfalls: number;
  evidence: {
    thinking: string;
    algorithm: string;
    implementation: string;
    pitfalls: string;
  };
  cf_rating?: number;
}

export interface EnrichQualityPayload {
  overall: number;
  completeness: number;
  examples: number;
  judge_config: number;
  data_strength: number;
  sources: {
    completeness: string;
    examples: string;
    judge_config: string;
    data_strength: string;
  };
  evidence: Record<string, string>;
}

export interface EnrichSuggestion {
  dimension: string;
  severity: string; // info / warn / block
  evidence: string;
  suggestion: string;
  status: string; // open / done / ignored
}

export interface EnrichSuggestionPayload {
  items: EnrichSuggestion[];
}

export interface EnrichTagsPayload {
  raw: string[];
  canonical: string[];
  candidate: string[];
}

// 审核队列一行（EnrichReviewItem）
export interface EnrichReviewItem {
  id: number;
  problem_id: number;
  task_type: string;
  model: string;
  prompt_ver: string;
  schema_ver: string;
  confidence: number;
  payload: Record<string, unknown>;
  raw_response?: string;
  visibility: string;
  source: string;
  golden: boolean;
  review_status: ReviewStatus;
  insert_time: string;
  problem_title: string;
}

// 黄金集一致率报告
export interface EnrichConsistencyItem {
  problem_id: number;
  task_type: string;
  golden: number;
  latest_ai: number; // -1 表示缺失
  exact_match: boolean;
  within_one: boolean;
}

export interface EnrichConsistencyReport {
  task_type: string;
  golden_total: number;
  comparable: number;
  missing: number;
  exact_match: number;
  within_one: number;
  exact_rate: number;
  within_one_rate: number;
  threshold: number;
  passed: boolean;
  details: EnrichConsistencyItem[];
}

// worker 运行配置（EnrichCronConfig 无 json tag，按 Go 字段名序列化；
// Interval/StaleTimeout 是 time.Duration，序列化为纳秒数字）
export interface EnrichWorkerConfig {
  // worker 运行的进程层：富化 worker 常驻 judge，web 只返回 Tier 标识
  Tier?: string;
  Enabled?: boolean;
  DryRun?: boolean;
  Interval?: number;
  BatchSize?: number;
  MaxAttempt?: number;
  StaleTimeout?: number;
  DailyTokenLimit?: number;
  DailyProblemLimit?: number;
  CandidatePromoteUsage?: number;
  Model?: string;
}

export interface EnrichPage<T> {
  list: T[];
  total: number;
}
